from fastapi import APIRouter
from pydantic import BaseModel
from pymongo.errors import DuplicateKeyError

from . import ledger
from .db import get_db

router = APIRouter()


class PaymentNotification(BaseModel):
    id: str
    customer_id: str
    amount: int


@router.post("/webhooks/provider")
def handle_provider_event(notification: PaymentNotification) -> dict:
    db = get_db()
    payments = db.payments
    try:
        payments.insert_one(
            {
                "provider_event_id": notification.id,
                "customer_id": notification.customer_id,
                "amount": notification.amount,
            }
        )
    except DuplicateKeyError:
        # Redelivery of an already-recorded event: do not double-record.
        # Only credit if the earlier attempt never reached the ledger.
        if db.ledger.find_one({"event_id": notification.id}) is None:
            ledger.credit(notification.customer_id, notification.amount, notification.id)
        return {"ok": True, "duplicate": True}
    ledger.credit(notification.customer_id, notification.amount, notification.id)
    return {"ok": True}

